function GlobalSearchResults({query,orders,onSelect}){const q=query.trim().toLowerCase();const assignmentResults=routingAssignments.filter(x=>`${x.customer} ${x.retailer} ${x.facility} ${x.name}`.toLowerCase().includes(q)).slice(0,6);const orderResults=orders.filter(x=>`${x.id} ${x.retailer} ${x.po} ${x.facility}`.toLowerCase().includes(q)).slice(0,4);const facilityResults=wiseFacilities.filter(x=>x.toLowerCase().includes(q)).slice(0,4);const tabResults=nav.filter(([label])=>label.toLowerCase().includes(q)).slice(0,3);const count=assignmentResults.length+orderResults.length+facilityResults.length+tabResults.length;return <div className="global-results">{count?<><p>Search results</p>{orderResults.map(row=><button key={`o-${row.id}`} onClick={()=>onSelect({type:'order',row})}><span className="result-type">ORDER</span><div><b><Highlight text={row.id} query={query}/></b><span><Highlight text={`${row.retailer} · ${row.facility}`} query={query}/></span></div></button>)}{assignmentResults.map(row=><button key={`a-${row.id}-${row.name}`} onClick={()=>onSelect({type:'assignment',row})}><span className="result-type">ASSIGNMENT</span><div><b><Highlight text={`${row.customer} — ${row.retailer}`} query={query}/></b><span><Highlight text={`${row.name} · ${row.facility}`} query={query}/></span></div></button>)}{facilityResults.map(label=><button key={`f-${label}`} onClick={()=>onSelect({type:'facility',label})}><span className="result-type">FACILITY</span><div><b><Highlight text={label} query={query}/></b><span>Open facility retailer directory</span></div></button>)}{tabResults.map(([label])=><button key={`t-${label}`} onClick={()=>onSelect({type:'tab',label})}><span className="result-type">TAB</span><div><b><Highlight text={label} query={query}/></b><span>Open page</span></div></button>)}</>:<div className="no-global-results">No matching orders, assignments, facilities, or tabs.</div>}</div>}
function normalizeRetailerName(value){let x=String(value||'').toUpperCase().replace(/[^A-Z0-9]/g,'');const aliases={WALMARTCOM:'WALMART',WALMART:'WALMART',AMAZONCOM:'AMAZON',AMAZONDF:'AMAZON',COSTCOWHOLESALECORP:'COSTCO',COSTCOCOM:'COSTCO',COSTCOECOMMERCE:'COSTCO',THEHOMEDEPOT:'HOMEDEPOT',HOMEDEPOT:'HOMEDEPOT',SAMSCLUB:'SAMSCLUB',SAMCLUBS:'SAMSCLUB',SAMS:'SAMSCLUB',KOHLSCORPORATION:'KOHLS',KOHLS:'KOHLS',BESTBUY:'BESTBUY',TJMAXXHOMEGOODS:'TJMAXXHOMEGOODS'};return aliases[x]||x}
